--信用债单笔交易净价信用sql中过滤交易的有效状态
delete from RSK_ISUP_INDICATOR_PARA_DTL where PARA_CODE = 'XYZDBJYJJ' and PARA_GRANULARITY IN('04','05');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('XYZDBJYJJ', '04', 'SQL', 'SELECT DISTINCT n.UNIT_CPRICE as RVALUE ,n.FINPROD_ID RKEY 
  from TRD_PRODUCT_DEAL_ADD m 
  inner join TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.FINPROD_TYPE2 =''F01'' AND n.PS IN (''T01'',''T02'',''T03'') and n.TRADE_STATUS != ''03'' and n.IS_CANCEL = ''N''
  INNER JOIN FIN_PRODUCT_TYPE s ON s.FINPROD_ID=n.FINPROD_ID AND s.BRANCH=0 AND (s.TYPE_6 IN (''B10'',''B11'',''B13'',''B14'',''B15'',''B04'',''B16'',''B06'',''B07'',''B08'',''B09'') OR (s.TYPE_6=''B05'' AND s.TYPE_7 <> ''01''))
  where  m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}'' 
  UNION all 
  select DISTINCT n.UNIT_CPRICE as RVALUE ,n.FINPROD_ID RKEY 
  from WFL_TRD_PRODUCT_DEAL_ADD m 
  inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.FINPROD_TYPE2 =''F01'' AND n.PS IN (''T01'',''T02'',''T03'') and n.TRADE_STATUS != ''03'' and n.IS_CANCEL = ''N''
  INNER JOIN FIN_PRODUCT_TYPE s ON s.FINPROD_ID=n.FINPROD_ID AND s.BRANCH=0 AND (s.TYPE_6 IN (''B10'',''B11'',''B13'',''B14'',''B15'',''B04'',''B16'',''B06'',''B07'',''B08'',''B09'') OR (s.TYPE_6=''B05'' AND s.TYPE_7<>''01'')) 
  where  m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}''', 'assetCode', 'N', 'jl', '001', TIMESTAMP '2020-07-29 11:27:38', 'jl1', TIMESTAMP '2020-07-29 11:29:08');
